-- System starter labs are independent of lecturer-owned modules.
ALTER TABLE labs ALTER COLUMN module_id DROP NOT NULL;
ALTER TABLE labs ALTER COLUMN created_by DROP NOT NULL;
ALTER TABLE labs ADD COLUMN is_starter boolean NOT NULL DEFAULT false;
ALTER TABLE labs ADD CONSTRAINT labs_scope_check CHECK (
  (is_starter AND module_id IS NULL AND created_by IS NULL AND status='published')
  OR (NOT is_starter AND module_id IS NOT NULL AND created_by IS NOT NULL)
);
CREATE INDEX labs_starter_catalogue_idx ON labs(kind,created_at DESC) WHERE is_starter;

INSERT INTO labs(lab_id,kind,title,instructions,difficulty,status,is_starter,config) VALUES ('00000000-0000-4000-8000-000000000101','code','HTML essentials','Add a main heading and a paragraph. Run your code to check both elements.',1,'published',true,'{"starterHtml": "<!-- Add your heading and paragraph below. -->", "starterCss": "body { font-family: sans-serif; padding: 16px; }", "starterJs": "", "checks": [{"type": "element_exists", "selector": "h1", "hint": "Add an h1 heading."}, {"type": "element_exists", "selector": "p", "hint": "Add a paragraph using p."}]}'::jsonb) ON CONFLICT (lab_id) DO NOTHING;
INSERT INTO labs(lab_id,kind,title,instructions,difficulty,status,is_starter,config) VALUES ('00000000-0000-4000-8000-000000000102','spreadsheet','Monthly budget','Enter a formula in C2 to subtract expenses (B2) from income (A2). Save your draft to check your work.',1,'published',true,'{"startingGrid": {"A1": "Income", "B1": "Expenses", "C1": "Balance", "A2": "12000", "B2": "6700", "C2": ""}, "lockedCells": ["A1", "B1", "C1"], "checks": [{"cell": "C2", "expected": 5300, "tolerance": 0.01, "requiresFormula": true, "hint": "Subtract B2 from A2 using a formula in C2."}], "currencySymbol": "R", "formats": {"C2": "currency"}}'::jsonb) ON CONFLICT (lab_id) DO NOTHING;
INSERT INTO labs(lab_id,kind,title,instructions,difficulty,status,is_starter,config) VALUES ('00000000-0000-4000-8000-000000000103','calculator','Break-even explorer','Change the costs and selling price to explore how many units cover your fixed costs. Price must exceed variable cost for a viable break-even point.',1,'published',true,'{"template": "break_even", "inputs": [{"key": "fixed_costs", "label": "Fixed costs", "defaultValue": 10000, "unit": "R"}, {"key": "price", "label": "Price per unit", "defaultValue": 50, "unit": "R"}, {"key": "variable_cost", "label": "Variable cost per unit", "defaultValue": 30, "unit": "R"}], "outputs": [{"key": "units", "label": "Break-even units", "formula": "{fixed_costs}/({price}-{variable_cost})", "explanation": "Fixed costs divided by contribution per unit."}]}'::jsonb) ON CONFLICT (lab_id) DO NOTHING;
INSERT INTO labs(lab_id,kind,title,instructions,difficulty,status,is_starter,config) VALUES ('00000000-0000-4000-8000-000000000104','scenario','Customer service decisions','Choose how to respond to a delayed order, then reflect on the trade-off between cost and customer trust.',1,'published',true,'{"meters": [{"key": "trust", "label": "Customer trust", "initial": 50}, {"key": "budget", "label": "Budget", "initial": 50}], "nodes": [{"id": "start", "text": "A customer reports a delayed order. What do you do?", "choices": [{"label": "Explain the delay and offer an update", "next": "explain", "changes": {"trust": 15}}, {"label": "Offer an immediate refund", "next": "refund", "changes": {"trust": 25, "budget": -20}}], "terminal": false}, {"id": "explain", "text": "You explain the delay.", "choices": [], "terminal": true, "reflection": "Clear communication builds trust while protecting the budget. Consider when a refund would be fairer."}, {"id": "refund", "text": "You offer a refund.", "choices": [], "terminal": true, "reflection": "A refund can restore trust, but costs money. Consider how a clear delivery update could help too."}]}'::jsonb) ON CONFLICT (lab_id) DO NOTHING;
